def is_valid_ts(s):

    if not is_string(s):
        return False

    #Checking for only numeric characters and length of 13
    #TODO - will need to change this length to 14 in the year 2286!!!  :)
    if not re.match("^[0-9]*$", s) or len(s) < 13 or len(s) > 14:
        return False
    try:
        val = int(s)
        if val < 0:
            return False

        return True
    except ValueError:
        return False

